def first_query_flags(rows):
    """1 for the first query after the set changes, 0 for a repeat of the
    previous trial's set (previous = the preceding row, when trial indices are
    given it must be trial_index - 1 of the same participant)."""
    flags = np.ones(len(rows))
    for i in range(1, len(rows)):
        r, q = rows[i], rows[i - 1]
        if str(r["number_set"]) != str(q["number_set"]):
            continue
        if str(r.get("participant_id", "")) != str(q.get("participant_id", "")):
            continue
        try:
            if int(r["trial_index"]) != int(q["trial_index"]) + 1:
                continue
        except (KeyError, TypeError, ValueError):
            pass
        flags[i] = 0.0
    return flags

